<script setup lang="ts">
import AdminConsole from '../console/AdminConsole.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleDialog from '../console/ConsoleDialog.vue'
import DecorationPreview from '../console/DecorationPreview.vue'
import PhonePreviewFrame from '../console/PhonePreviewFrame.vue'
import MaterialPicker from '../console/MaterialPicker.vue'
import {normalizeDecorationScheme,decorationNavigation,decorationPageBackground} from '../../../../api/src/core/decoration-contract.mjs'
import {dateTime} from '../../utils/update-center'
import type {DecorationView,DecorationRecord} from '../../utils/decoration'
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,route=useRoute(),endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/decoration',toast=useToast()
const initial=await useAsyncData('decoration-library:'+auth.session.value?.id+':'+tenantId+':'+String(route.query.application||''),(_,{signal})=>auth.api<DecorationView>(endpoint+(typeof route.query.application==='string'?'?applicationKey='+encodeURIComponent(route.query.application):''),'GET',undefined,{signal}))
const data=ref<DecorationView|null>(initial.data.value||null),error=ref(initial.error.value?.message||''),busy=ref(''),templateSource=useRouteTab<'system'|'mine'>('system',['system','mine']),search=ref(''),groupFilter=ref('all')
const dialog=ref<'rename'|'delete'|'move'|null>(null),target=ref<DecorationRecord|null>(null),name=ref(''),selectedGroup=ref(''),dialogError=ref(''),preview=ref<DecorationRecord|null>(null),previewPage=ref<'home'|'profile'>('home')
const groupsOpen=ref(false),groupName=ref(''),editingGroupId=ref(''),groupError=ref(''),deletingGroup=ref<{id:string;name:string}|null>(null),coverOpen=ref(false),coverTarget=ref<DecorationRecord|null>(null)
const rows=computed(()=>(templateSource.value==='system'?data.value?.systemTemplates:data.value?.templates)||[]),visibleRows=computed(()=>rows.value.filter(r=>r.name.includes(search.value.trim())&&(groupFilter.value==='all'||(groupFilter.value==='ungrouped'?!r.groupId:r.groupId===groupFilter.value))))
const locked=computed(()=>!!busy.value||!data.value?.canWrite),lifetime=new AbortController();let disposed=false
const applyUrl=(row:DecorationRecord)=>'/admin/decoration-editor?application='+encodeURIComponent(data.value?.applicationKey||'')+'&template='+encodeURIComponent(row.id)
function open(action:'rename'|'delete'|'move',row:DecorationRecord){if(locked.value||row.source==='system')return;dialog.value=action;target.value=row;name.value=row.name;selectedGroup.value=row.groupId||'';dialogError.value=''}
function close(){if(!busy.value){dialog.value=null;dialogError.value=''}}
async function refresh(applicationKey=data.value?.applicationKey||'',action='refresh'){if(busy.value)return;busy.value=action;error.value='';try{const result=await auth.api<DecorationView>(endpoint+(applicationKey?'?applicationKey='+encodeURIComponent(applicationKey):''),'GET',undefined,{signal:lifetime.signal});if(!disposed)data.value=result}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=''}}
async function submit(){if(locked.value||!dialog.value||!target.value||!data.value?.applicationKey)return;const action=dialog.value,row=target.value;if(action==='rename'&&!name.value.trim()){dialogError.value='请填写模板名称';return}busy.value=action+':'+row.id;dialogError.value='';try{const input={version:data.value.version,id:row.id,action:action==='rename'?'save-template':action==='move'?'set-group':'delete-template',...(action==='rename'?{name:name.value.trim(),scheme:row.scheme}:action==='move'?{groupId:selectedGroup.value||null}:{})};const result=await auth.api<DecorationView>(endpoint+'/'+encodeURIComponent(data.value.applicationKey),'PUT',input,{signal:lifetime.signal});if(disposed)return;data.value=result;dialog.value=null;toast.add({title:action==='delete'?'模板已删除':'模板已保存',color:'success'})}catch(e:any){if(!disposed)dialogError.value=e.message}finally{if(!disposed)busy.value=''}}
async function metadata(action:string,id:string,fields:Record<string,unknown>={}){if(locked.value||!data.value?.applicationKey)return false;busy.value=action+':'+id;groupError.value='';error.value='';try{const result=await auth.api<DecorationView>(endpoint+'/'+encodeURIComponent(data.value.applicationKey),'PUT',{action,id,version:data.value.version,...fields},{signal:lifetime.signal});if(disposed)return false;data.value=result;return true}catch(e:any){if(!disposed){if(action.startsWith('group-'))groupError.value=e.message;else error.value=e.message}return false}finally{if(!disposed)busy.value=''}}
async function saveGroup(){if(!groupName.value.trim()){groupError.value='请填写分类名称';return}if(await metadata('group-save',editingGroupId.value||crypto.randomUUID(),{name:groupName.value.trim()})){groupName.value='';editingGroupId.value=''}}
async function deleteGroup(){if(!deletingGroup.value)return;const id=deletingGroup.value.id;if(await metadata('group-delete',id)){if(groupFilter.value===id)groupFilter.value='ungrouped';deletingGroup.value=null}}
function chooseCover(row:DecorationRecord){if(locked.value||row.source==='system')return;coverTarget.value=row;coverOpen.value=true}
async function setCover(image:{id:string}){if(coverTarget.value)await metadata('set-cover',coverTarget.value.id,{coverId:image.id})}
function imageUrl(id:string){return '/api/v1/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data.value?.applicationKey||'')+'/'+encodeURIComponent(id)+'/content?purpose=library'}
onBeforeUnmount(()=>{disposed=true;lifetime.abort()})
</script>
<template><AdminConsole :refreshing="busy==='refresh'" @refresh="refresh()"><div class="space-y-5"><ConsolePageHeading title="模板库"><template #actions><UButton to="/admin/decoration" color="neutral" variant="outline" icon="i-lucide-layout-grid">当前装修</UButton></template></ConsolePageHeading><UAlert v-if="error" color="error" :title="error"/>
<div class="flex flex-wrap gap-2" role="tablist" aria-label="模板来源"><UButton v-for="entry in ([{key:'system',label:'系统模板'},{key:'mine',label:'我的模板'}] as const)" :key="entry.key" role="tab" :aria-selected="templateSource===entry.key" :variant="templateSource===entry.key?'solid':'ghost'" color="neutral" @click="templateSource=entry.key;groupFilter='all';search=''">{{entry.label}}</UButton></div>
<div class="scheme-list-toolbar"><div class="scheme-search"><UIcon name="i-lucide-search"/><input v-model="search" placeholder="搜索模板" aria-label="搜索模板"></div><USelect v-if="templateSource==='mine'" v-model="groupFilter" :items="[{label:'全部分类',value:'all'},{label:'未分类',value:'ungrouped'},...(data?.groups||[]).map(g=>({label:g.name,value:g.id}))]" class="w-40" aria-label="筛选分类"/><UButton v-if="templateSource==='mine'" color="neutral" variant="ghost" icon="i-lucide-folder" @click="groupsOpen=true">管理分类</UButton><span class="text-xs text-muted">共 {{rows.length}} 个模板</span><USelect v-if="data&&data.applications.length>1" :model-value="data.applicationKey||undefined" :items="data.applications.map(a=>({value:a.key,label:a.name}))" :disabled="!!busy" :loading="busy==='switch'" aria-label="选择应用" placeholder="选择应用" class="ml-auto w-44" @update:model-value="refresh(String($event),'switch')"/></div>
<div v-if="visibleRows.length" class="scheme-grid"><article v-for="row in visibleRows" :key="row.id" class="scheme-card"><div role="button" tabindex="0" class="scheme-cover" :aria-label="'预览 '+row.name" @click="preview=row;previewPage='home'" @keydown.enter="preview=row;previewPage='home'"><img v-if="row.coverId" class="scheme-cover-image" :src="imageUrl(row.coverId)" :alt="row.name+'封面'"><div v-else class="scheme-cover-render" aria-hidden="true" inert><DecorationPreview :assets="data?.assets" :components="data?.components" :scheme="normalizeDecorationScheme(row.scheme)" page="home" :image-url="imageUrl"/></div><span class="scheme-cover-open"><UIcon name="i-lucide-eye"/>预览模板</span></div><div class="scheme-info"><div class="scheme-card-title"><h2>{{row.name}}</h2><span>{{row.source==='system'?'系统模板':'我的模板'}}</span></div><p>首页 · 个人中心 · 主题 · 底部导航</p><p class="scheme-date">{{row.source==='system'?'系统内置':(data?.groups.find(g=>g.id===row.groupId)?.name||'未分类')+' · '+dateTime(row.updatedAt)}}</p><div class="scheme-main-action"><UButton :to="applyUrl(row)" target="_blank" rel="noopener" :disabled="!data?.canWrite" icon="i-lucide-mouse-pointer-2" variant="soft" block>套用并装修</UButton></div><div v-if="row.source!=='system'" class="scheme-actions"><UButton color="neutral" variant="ghost" size="xs" :disabled="locked" :loading="busy==='rename:'+row.id" @click="open('rename',row)">重命名</UButton><UButton color="neutral" variant="ghost" size="xs" :disabled="locked" :loading="busy==='set-cover:'+row.id" @click="chooseCover(row)">封面</UButton><UButton color="neutral" variant="ghost" size="xs" :disabled="locked" @click="open('move',row)">分类</UButton><UButton color="error" variant="ghost" size="xs" :disabled="locked" :loading="busy==='delete:'+row.id" @click="open('delete',row)">删除</UButton></div></div></article></div>
<div v-else-if="data" class="scheme-empty"><UIcon name="i-lucide-bookmark" class="text-4xl text-muted"/><h2>{{search?'没有匹配的模板':templateSource==='system'?'当前应用暂无系统模板':'还没有保存模板'}}</h2><p v-if="templateSource==='mine'">在当前装修中点击“存为模板”，即可保留一份独立设计。</p></div>
<ConsoleDialog :open="!!dialog" :title="dialog==='rename'?'重命名模板':dialog==='move'?'移动分类':'删除模板'" :description="dialog==='delete'?'删除模板不影响已经套用到当前装修的内容。':undefined" :dismissible="!busy" :close="!busy" @update:open="!$event&&close()"><template #body><form id="template-dialog" class="space-y-4" @submit.prevent="submit"><UAlert v-if="dialogError" color="error" :title="dialogError"/><UFormField v-if="dialog==='rename'" label="模板名称" :ui="{container:'mt-2'}"><ConsoleInput v-model="name" required :maxlength="40" :disabled="!!busy"/></UFormField><UFormField v-else-if="dialog==='move'" label="分类" :ui="{container:'mt-2'}"><USelect :model-value="selectedGroup||'ungrouped'" :items="[{label:'未分类',value:'ungrouped'},...(data?.groups||[]).map(g=>({label:g.name,value:g.id}))]" class="w-full" :disabled="!!busy" @update:model-value="selectedGroup=$event==='ungrouped'?'':$event"/></UFormField><p v-else>{{target?.name}}</p></form></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="!!busy" @click="close">取消</UButton><UButton type="submit" form="template-dialog" :color="dialog==='delete'?'error':'primary'" :disabled="locked" :loading="!!busy&&busy.startsWith((dialog||'')+':')">{{dialog==='delete'?'确认删除':'保存'}}</UButton></ConsoleFormActions></template></ConsoleDialog>
<ConsoleDialog :open="!!preview" :title="preview?.name||'预览模板'" size="content" @update:open="!$event&&(preview=null)"><template #body><div v-if="preview" class="template-preview-stage"><div class="scheme-preview-tabs"><UButton v-for="page in ([{key:'home',label:'首页'},{key:'profile',label:'个人中心'}] as const)" :key="page.key" color="neutral" :variant="previewPage===page.key?'solid':'outline'" @click="previewPage=page.key">{{page.label}}</UButton></div><div class="template-preview-phone"><PhonePreviewFrame :bottom-color="preview.scheme.navigation.enabled?decorationNavigation(preview.scheme).background:decorationPageBackground(preview.scheme,previewPage)"><DecorationPreview :assets="data?.assets" :components="data?.components" :scheme="normalizeDecorationScheme(preview.scheme)" :page="previewPage" :image-url="imageUrl" @navigate="($event==='home'||$event==='profile')&&(previewPage=$event)"/></PhonePreviewFrame></div></div></template></ConsoleDialog>
<MaterialPicker v-model:open="coverOpen" portal="tenant" purpose="library" kind="image" :endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data?.applicationKey||'')" @select="setCover"/>
<ConsoleDialog v-model:open="groupsOpen" title="管理分类" :dismissible="!busy" :close="!busy"><template #body><UAlert v-if="groupError" color="error" :title="groupError" class="mb-4"/><form class="group-create-form" @submit.prevent="saveGroup"><div class="group-create-input"><ConsoleInput v-model="groupName" :maxlength="20" :disabled="locked" :placeholder="editingGroupId?'输入新的分类名称':'新建分类名称'" required aria-label="分类名称"/></div><UButton type="submit" :disabled="locked" :loading="busy.startsWith('group-save:')">{{editingGroupId?'保存':'添加'}}</UButton><UButton v-if="editingGroupId" color="neutral" variant="ghost" :disabled="!!busy" @click="editingGroupId='';groupName=''">取消</UButton></form><div v-for="group in data?.groups||[]" :key="group.id" class="scheme-group-row"><span>{{group.name}}</span><small>{{data?.templates.filter(t=>t.groupId===group.id).length}} 个模板</small><UButton color="neutral" variant="ghost" size="xs" :disabled="locked" @click="editingGroupId=group.id;groupName=group.name">重命名</UButton><UButton color="error" variant="ghost" size="xs" :disabled="locked" @click="deletingGroup=group">删除</UButton></div><p v-if="!data?.groups.length" class="py-8 text-center text-muted">暂无分类</p></template></ConsoleDialog>
<ConsoleDialog :open="!!deletingGroup" title="删除分类" description="其中的模板将移到“未分类”，内容不会被删除。" :dismissible="!busy" :close="!busy" @update:open="!$event&&(deletingGroup=null)"><template #body><p>{{deletingGroup?.name}}</p></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="!!busy" @click="deletingGroup=null">取消</UButton><UButton color="error" :disabled="locked" :loading="busy.startsWith('group-delete:')" @click="deleteGroup">确认删除</UButton></ConsoleFormActions></template></ConsoleDialog>
</div></AdminConsole></template>
<style scoped>
