display:flex;align-items:center;flex-direction:column;padding:72px 20px;border:1px dashed var(--ui-border);border-radius:10px;background:var(--ui-bg)}.scheme-empty-icon{display:grid;place-items:center;width:60px;height:60px;border-radius:16px;background:var(--ui-bg-elevated);color:var(--ui-text-dimmed);font-size:28px;margin-bottom:16px}.scheme-empty h2{font-size:16px;font-weight:600}.scheme-empty p{font-size:13px;color:var(--ui-text-muted);margin-top:8px}.scheme-list-toolbar select{border:1px solid var(--ui-border);border-radius:6px;padding:6px;background:var(--ui-bg)}@media(max-width:640px){.scheme-grid{grid-template-columns:1fr}.scheme-card{max-width:none}.scheme-empty{padding:48px 16px}}
.active-scheme{display:flex;align-items:center;gap:16px;padding:20px 24px;border:1px solid var(--ui-border);border-radius:12px;background:var(--ui-bg)}.active-scheme-icon{display:grid;place-items:center;background:color-mix(in srgb,var(--ui-primary) 8%,var(--ui-bg));color:var(--ui-primary);width:48px;height:48px;border-radius:12px;font-size:22px;flex-shrink:0}.active-scheme h2{font-size:15px;font-weight:600;margin-top:3px}.active-scheme p{font-size:11px;color:var(--ui-text-muted);margin-top:4px}.scheme-search{display:flex;align-items:center;gap:9px;width:270px;border:1px solid var(--ui-border);border-radius:8px;padding:9px 12px;background:var(--ui-bg);color:var(--ui-text-muted)}.scheme-search input{min-width:0;width:100%;background:transparent;outline:0;font-size:13px;color:var(--ui-text)}.scheme-cover{width:100%;border:0;cursor:pointer}.scheme-card{padding:0;border-radius:12px;max-width:none;transition:box-shadow .15s}.scheme-card:hover{box-shadow:0 5px 20px #0f172a08}.scheme-cover{border-radius:0;height:210px;background:linear-gradient(135deg,var(--ui-bg-elevated),var(--ui-bg-muted))}.scheme-info{padding:18px}.scheme-card-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.scheme-card-title h2{min-width:0}.scheme-card-title>span{font-size:10px;white-space:nowrap;color:var(--ui-text-muted);background:var(--ui-bg-elevated);padding:3px 6px;border-radius:4px}.scheme-main-action{margin:16px 0 10px}.scheme-actions{justify-content:space-between;border-top:1px solid var(--ui-border);padding-top:10px}.scheme-create-card{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:16px;border:1px dashed var(--ui-border-accented);border-radius:12px;min-height:370px;cursor:pointer;color:var(--ui-text-muted)}.scheme-create-card>span{display:grid;place-items:center;width:48px;height:48px;background:var(--ui-bg-elevated);border-radius:50%;font-size:22px}.scheme-create-card strong{font-size:14px;font-weight:500;color:var(--ui-text)}.scheme-create-card small{font-size:12px}.scheme-create-card:hover{border-color:var(--ui-primary);color:var(--ui-primary)}.scheme-list-toolbar{flex-wrap:wrap}.scheme-grid{grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:22px}.scheme-date{font-size:10px!important}@media(max-width:640px){.active-scheme{padding:16px;flex-wrap:wrap}.scheme-search{width:100%}.scheme-grid{grid-template-columns:1fr}}
.scheme-preview-dialog{height:100%;display:flex;flex-direction:column;min-height:0;padding:16px 24px 22px;gap:14px}.scheme-preview-tabs{display:flex;justify-content:center;gap:8px;flex-shrink:0}.scheme-preview-phone{flex:1;min-height:0;width:100%}
.scheme-category-select{border:1px solid var(--ui-border);border-radius:7px;padding:8px 10px;background:var(--ui-bg);font-size:12px}.scheme-cover-image{width:100%;height:100%;object-fit:contain;padding:8px}.scheme-cover-actions{display:flex;align-items:center;flex-wrap:wrap;gap:2px;margin-top:8px}.scheme-group-row{display:flex;align-items:center;gap:6px;padding:10px 0;border-top:1px solid var(--ui-border)}.scheme-group-row>span{flex:1;font-size:13px}.scheme-group-row>small{color:var(--ui-text-muted);font-size:11px}.scheme-grid{align-items:stretch}
.group-create-form{display:flex;align-items:center;gap:10px;margin-bottom:20px}.group-create-input{flex:1;min-width:0}.group-create-form>button{flex-shrink:0;white-space:nowrap;min-height:34px}
</style>
